#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

#define MAX_LOG_ENTRY 4096
#define ENCRYPTED_STORE "/var/log/agent/encrypted.bin"
#define CONFIG_ENDPOINT_MAX 256

typedef struct {
    char collector_host[CONFIG_ENDPOINT_MAX];
    uint16_t collector_port;
    unsigned char aes_key[32];
    unsigned char aes_iv[16];
    int verify_collector;
} agent_config_t;

typedef struct {
    char source[64];
    char message[MAX_LOG_ENTRY];
    time_t timestamp;
} log_entry_t;

static agent_config_t g_config;

int encrypt_and_store(const log_entry_t *entry, FILE *store) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    unsigned char ciphertext[MAX_LOG_ENTRY + EVP_MAX_BLOCK_LENGTH];
    int len, ciphertext_len;

    if (!ctx) return -1;
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, g_config.aes_key, g_config.aes_iv);
    EVP_EncryptUpdate(ctx, ciphertext, &len, (unsigned char*)entry->message, strlen(entry->message));
    ciphertext_len = len;
    EVP_EncryptFinal_ex(ctx, ciphertext + len, &len);
    ciphertext_len += len;
    EVP_CIPHER_CTX_free(ctx);

    fwrite(&ciphertext_len, sizeof(int), 1, store);
    fwrite(ciphertext, 1, ciphertext_len, store);
    fflush(store);
    return 0;
}

/* Resolve collector address - supports service discovery via DNS */
static int resolve_collector_addr(const char *host, struct sockaddr_in *addr) {
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    if (getaddrinfo(host, NULL, &hints, &res) != 0)
        return -1;

    memcpy(addr, res->ai_addr, sizeof(struct sockaddr_in));
    freeaddrinfo(res);
    return 0;
}

/* Forward log to central collector over TCP */
int forward_to_collector(const log_entry_t *entry) {
    struct sockaddr_in collector_addr;
    int sock;
    char payload[MAX_LOG_ENTRY + 128];

    if (resolve_collector_addr(g_config.collector_host, &collector_addr) < 0)
        return -1;

    collector_addr.sin_port = htons(g_config.collector_port);

    sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) return -1;

    if (connect(sock, (struct sockaddr*)&collector_addr, sizeof(collector_addr)) < 0) {
        close(sock);
        return -1;
    }

    snprintf(payload, sizeof(payload), "{\"source\":\"%s\",\"ts\":%ld,\"msg\":\"%s\"}",
             entry->source, entry->timestamp, entry->message);
    send(sock, payload, strlen(payload), 0);
    close(sock);
    return 0;
}

/* Parse dynamic config update from collector response.
 * Format: "REDIRECT:<host>:<port>" allows collector migration.
 * Security: only internal 10.x.x.x addresses are permitted for redirect. */
int handle_config_update(const char *response) {
    char new_host[CONFIG_ENDPOINT_MAX];
    int new_port;
    struct in_addr check_addr;

    if (strncmp(response, "REDIRECT:", 9) != 0)
        return 0;

    if (sscanf(response + 9, "%255[^:]:%d", new_host, &new_port) != 2)
        return -1;

    /* Validate: resolve and check it's in 10.0.0.0/8 */
    struct sockaddr_in resolved;
    if (resolve_collector_addr(new_host, &resolved) < 0)
        return -1;

    check_addr = resolved.sin_addr;
    uint32_t addr_host_order = ntohl(check_addr.s_addr);

    /* Check first octet is 10 (0x0A) */
    if ((addr_host_order >> 24) != 0x0A) {
        fprintf(stderr, "Redirect rejected: not in 10.0.0.0/8\n");
        return -1;
    }

    /* Validation passed - update config */
    strncpy(g_config.collector_host, new_host, CONFIG_ENDPOINT_MAX - 1);
    g_config.collector_port = (uint16_t)new_port;
    return 1;
}

/* Poll collector for commands and config updates */
int poll_collector(void) {
    struct sockaddr_in collector_addr;
    int sock;
    char buf[1024];
    ssize_t n;

    if (resolve_collector_addr(g_config.collector_host, &collector_addr) < 0)
        return -1;

    collector_addr.sin_port = htons(g_config.collector_port);
    sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) return -1;

    if (connect(sock, (struct sockaddr*)&collector_addr, sizeof(collector_addr)) < 0) {
        close(sock);
        return -1;
    }

    send(sock, "POLL\n", 5, 0);
    n = recv(sock, buf, sizeof(buf) - 1, 0);
    close(sock);

    if (n > 0) {
        buf[n] = '\0';
        handle_config_update(buf);
    }
    return 0;
}

int init_agent(const char *collector, uint16_t port) {
    strncpy(g_config.collector_host, collector, CONFIG_ENDPOINT_MAX - 1);
    g_config.collector_port = port;
    g_config.verify_collector = 1;
    RAND_bytes(g_config.aes_key, 32);
    RAND_bytes(g_config.aes_iv, 16);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <collector_host> <port>\n", argv[0]);
        return 1;
    }

    init_agent(argv[1], (uint16_t)atoi(argv[2]));

    FILE *store = fopen(ENCRYPTED_STORE, "ab");
    if (!store) {
        perror("Failed to open encrypted store");
        return 1;
    }

    log_entry_t entry;
    strncpy(entry.source, "agent-01", sizeof(entry.source) - 1);
    entry.timestamp = time(NULL);

    while (fgets(entry.message, MAX_LOG_ENTRY, stdin)) {
        entry.message[strcspn(entry.message, "\n")] = '\0';
        encrypt_and_store(&entry, store);
        forward_to_collector(&entry);
        poll_collector();
        entry.timestamp = time(NULL);
    }

    fclose(store);
    return 0;
}
